import {readPostingPreview,type PostingPreview} from '@/lib/accounting';
import {validateAccountingRequest,accountingReceiptMatches,type AccountingPostingRequest} from '@/lib/accounting-request';
export type NightlyBatch={version:1;actor:string;tenant:string;property:string;request:string;items:{request_id:string;preview:PostingPreview}[]};
const uuid=(x:unknown):x is string=>typeof x==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(x);
const keys=(x:object,names:string[])=>Object.keys(x).sort().join(',')===names.sort().join(',');
const canonical=(value:unknown):string=>JSON.stringify(value&&typeof value==='object'?Array.isArray(value)?value.map(canonical):Object.keys(value).sort().map(k=>[k,canonical((value as Record<string,unknown>)[k])]):value);
function child(batch:NightlyBatch,item:NightlyBatch['items'][number]):AccountingPostingRequest{const p=item.preview;return {version:1,actor:batch.actor,tenant:batch.tenant,property:batch.property,request:item.request_id,kind:'service',reservation:p.reservation_id,serviceDate:p.service_date,adjustment:null,mapping:p.mapping_id,mappingVersion:p.mapping_version,period:p.period_id,postingDate:p.posting_date,noLines:p.lines.length===0};}
export function validateNightlyBatch(value:unknown):NightlyBatch{
 if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Batch recovery is unavailable.');const b=value as NightlyBatch;
 if(!keys(b,['version','actor','tenant','property','request','items'])||b.version!==1||![b.actor,b.tenant,b.property,b.request].every(uuid)||!Array.isArray(b.items)||b.items.length<1||b.items.length>100||new TextEncoder().encode(JSON.stringify(b.items)).length>2097152)throw Error('Invalid batch identity or size.');
 const requests=new Set([b.request]),sources=new Set<string>();
 for(const item of b.items){
  if(!item||typeof item!=='object'||!keys(item,['request_id','preview'])||!uuid(item.request_id)||requests.has(item.request_id))throw Error('Duplicate or invalid batch child request.');requests.add(item.request_id);
  const p=item.preview;
  if(!p||p.actor_id!==b.actor||p.tenant_id!==b.tenant||p.property_id!==b.property||Object.hasOwn(p,'adjustment_id')||p.already_processed!==false||p.existing_request_id!==null||p.existing_journal_id!==null)throw Error('Batch preview is already processed or belongs to another scope.');
  readPostingPreview(p,{tenant_id:b.tenant,property_id:b.property,reservation_id:p.reservation_id,service_date:p.service_date,mapping_id:p.mapping_id,period_id:p.period_id,posting_date:p.posting_date});
  validateAccountingRequest(child(b,item));
  if(p.total_minor.startsWith('-')||p.lines.some(line=>!uuid(line.account_id)))throw Error('Invalid nightly source amounts or accounts.');
  const source=p.service_date+'/'+p.reservation_id;if(sources.has(source))throw Error('A nightly source is repeated.');sources.add(source);
 }
 return b;
}
export function nightlyBatchKey(actor:string,tenant:string,property:string){if(![actor,tenant,property].every(uuid))throw Error('Verified batch scope required.');return 'iratepilot-pms-nightly-batch:'+actor+':'+tenant+':'+property;}
export function retainNightlyBatch(storage:Pick<Storage,'getItem'|'setItem'>,batch:NightlyBatch){validateNightlyBatch(batch);const key=nightlyBatchKey(batch.actor,batch.tenant,batch.property),text=JSON.stringify(batch),prior=storage.getItem(key);if(prior!==null&&prior!==text)throw Error('Resolve the retained nightly batch first.');storage.setItem(key,text);if(storage.getItem(key)!==text)throw Error('Nightly batch could not be retained.');}
export function readNightlyBatch(storage:Pick<Storage,'getItem'>,actor:string,tenant:string,property:string){const raw=storage.getItem(nightlyBatchKey(actor,tenant,property));if(raw===null)return null;const b=validateNightlyBatch(JSON.parse(raw));if(b.actor!==actor||b.tenant!==tenant||b.property!==property)throw Error('Retained batch belongs to another scope.');return b;}
export function nightlyBatchParams(batch:NightlyBatch){const b=validateNightlyBatch(batch);return {p_tenant:b.tenant,p_property:b.property,p_request:b.request,p_items:b.items,p_confirmed:true};}
function scoped(value:unknown,b:NightlyBatch):Record<string,unknown>{validateNightlyBatch(b);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Batch response unavailable.');const v=value as Record<string,unknown>;if(v.schema_version!==1||v.actor_id!==b.actor||v.tenant_id!==b.tenant||v.property_id!==b.property||v.request_id!==b.request)throw Error('Batch response belongs to another request.');return v;}
export function readNightlyBatchReceipt(value:unknown,b:NightlyBatch){const v=scoped(value,b);if(v.item_count!==b.items.length||typeof v.replayed!=='boolean'||!Array.isArray(v.receipts)||v.receipts.length!==b.items.length||!v.receipts.every((r,i)=>accountingReceiptMatches(r,child(b,b.items[i]))))throw Error('Batch receipts do not match every retained source.');return v;}
export function readNightlyBatchStatus(value:unknown,b:NightlyBatch){const v=scoped(value,b);if(typeof v.found!=='boolean')throw Error('Invalid batch status.');if(!v.found){if(v.command!==null||v.result!==null)throw Error('Invalid missing batch response.');return null;}if(canonical(v.command)!==canonical(b.items))throw Error('Saved batch differs from the retained review.');return readNightlyBatchReceipt(v.result,b);}
export function readNightlyBatchRetirement(value:unknown,b:NightlyBatch){const v=scoped(value,b);if(typeof v.retired!=='boolean'||typeof v.replayed!=='boolean')throw Error('Invalid batch cancellation.');if(!v.retired){if(v.command!==null||v.retired_at!==null)throw Error('Invalid missing cancellation.');return false;}if(canonical(v.command)!==canonical(b.items)||typeof v.retired_at!=='string'||!Number.isFinite(Date.parse(v.retired_at)))throw Error('Cancellation does not match the retained batch.');return true;}
export function clearNightlyBatch(storage:Pick<Storage,'getItem'|'removeItem'>,b:NightlyBatch,result:unknown,cancelled=false){if(cancelled){if(!readNightlyBatchRetirement(result,b))throw Error('Batch cancellation is not saved.');}else readNightlyBatchReceipt(result,b);const key=nightlyBatchKey(b.actor,b.tenant,b.property);if(storage.getItem(key)!==JSON.stringify(b))throw Error('Retained batch changed.');storage.removeItem(key);if(storage.getItem(key)!==null)throw Error('Retained batch could not be cleared.');}
